# Assemble /output/report.json from the analysis outputs in /workspace/out (re-runnable)
import json, pandas as pd, numpy as np
O='/workspace/out/'
fit=pd.read_csv(O+'s7_line_fits.csv'); weak=pd.read_csv(O+'s7c_weak_lines.csv'); bl=pd.read_csv(O+'s7d_blends.csv'); wing=pd.read_csv(O+'s8_wings.csv')
cont=pd.read_csv(O+'s6_continuum.csv')
VS=2780.0
A=lambda **k:[{'name':a,'value':str(b)} for a,b in k.items()]
base_ass=A(systemic_velocity='2780 km/s radio-LSRK (measured here, +-5)',noise='per-channel rms from line-free channels of the same spectrum; formal errors, adjacent-channel correlation (lag-1) included approximately',flux_scale='ALMA pbcor Jy/beam, no absolute calibration uncertainty included (typ. 10% Band 6/7, 5-10% Band 5)')
R=[]
def add(q,v,c,e,target=None,unc=None,unit=None,ass=None):
    R.append(dict(quantity=q,target=target,value=v,uncertainty=unc,unit=unit,assumptions=ass if ass is not None else base_ass,confidence=c,evidence=e))
# ---- systemic velocity
add('Systemic velocity from dense-gas lines','2780',"high",'scripts/s3b_systemic.py -> out/s3b_systemic.txt: first moment / half-maximum midpoint of HCN & HCO+ 2-1,3-2,4-3 in r=8" integrated and N/S peak spectra: 2769-2790 km/s (mean 2781)',target='NGC 3256 (whole)',unc='+-5 (spread between lines/regions)',unit='km/s (radio, LSRK)',ass=A(definition='v=c(1-nu/nu0), cube frame LSRK; nominal task value 2750 km/s is 30 km/s lower; optical-definition z=0.0094 corresponds to 2792 km/s radio'))
# ---- nuclei geometry
add('Nuclear positions (continuum peaks, 0.24" Band 6)','N: 156.96346,-43.90388 ; S: 156.96340,-43.90533 (ICRS deg); separation 5.2"','high','scripts/s1_continuum.py, s6_continuum.py -> out/s1_continuum.txt',target='N and S nuclei',unc='~0.05" (pixel 0.047")',unit='deg / arcsec',ass=A(distance='40 Mpc (Pereira-Santaella+2024) -> 194 pc/arcsec; 5.2" ~ 1.0 kpc; 0.24" ~ 47 pc'))
# ---- continuum
def crow(f,k): return cont[cont.file.str.startswith(f)].iloc[0][k]
c=cont.set_index('file')
def cv(name,col): return float(c.loc[name,col])
add('Continuum peak (line-free cont image, pbcor) in the 4 bands/arrays','Xb4b 0.24" 257.8 GHz: S 1.853, N 0.561, E1 0.389 mJy/beam (rms 0.020); Xb4d 0.94x0.74" 257.8 GHz: N 3.594, S 4.257 (rms 0.069); Xb4f 5.8x3.5" 257.7 GHz: N 19.35, S 13.95 (rms 0.61); Xb47 4.2x2.7" 346.5 GHz: N 36.46, S 22.04 (rms 1.4); Xb55 9x6" 170.7 GHz: single unresolved peak 14.95 (rms 0.29), N and S merged','high','scripts/s6_continuum.py -> out/s6_continuum.csv (rms = MAD in 6-12" annulus, includes faint sources: slightly conservative)',target='N, S',unc='statistical only: rms above; flux scale 5-10%',unit='mJy/beam')
add('Continuum morphology: S compact, N extended','S/N peak ratio = 3.3 at 0.24" but 1.2 at 0.94" and 0.7 at 5.8" (N brighter); r=2.5" aperture flux (0.24" mfs spw25): N 17.3, S 9.8 mJy; further sources E1 (156.96608,-43.90350; 0.39 mJy/beam at 0.24", 1.5 at 0.94"), SE (156.96685,-43.90635; 0.57 mJy/beam at 0.24" and 0.85-1.1 at 0.94": partly resolved; >5 sigma in all 4 Xb4b mfs) and ridge/bridge (156.96352,-43.90461; 0.9 mJy/beam at 0.94")','medium','out/s6_continuum.csv; aperture flux of the 0.24" map is affected by missing short spacings (negative bowls, e.g. SE r=2.5" sum is negative)',target='N, S, E1, SE',unit='mJy (r=2.5") / mJy/beam')
add('Line contamination of delivered mfs and cont images','none detected: residuals of every per-spw mfs from a power law through all images of the same OUS are <=0.7 mJy/beam at N (|resid|<=1 sigma), whereas inclusion of the lines would add 9.6 (HCN 4-3), 18.8 (HCO+ 4-3) mJy/beam in Xb47 N, 17 (HCO+ 3-2) in Xb4f N, 13.5 (HCO+ 2-1) in Xb55 N','high','scripts/s6b_cont_contam.py -> out/s6b_cont_contam.csv: expected = W_line(peak pixel)/bandwidth. mfs and cont are effectively line-free continuum images',target='N, S, all bands',unit='mJy/beam',ass=A(bandwidth='mfs bandwidth 1.5-1.9 GHz from headers',power_law='fitted per OUS/region over 5 images; alpha not constrained better than +-1 within one band'))
# ---- coverage / targeted lines
add('Targeted lines present in the data','HCN & HCO+ J=2-1 (Xb55 spw16/spw18), 3-2 (Xb4f/Xb4d/Xb4b spw18-27/spw16-25), 4-3 (Xb47 spw16/spw18): all detected at >100 sigma in N and S. CS 7-6 (Xb47 spw22): detected (N 15 sigma, S 7.5 sigma). H13CN 4-3 (Xb47 spw20): only the low-frequency half of the profile is covered and it lies on the blue wing of CO 3-2 (band edge, rest 345.60 GHz): not separable (see below). SO(6_5-5_4) 219.949 GHz is NOT covered by any file; SO lines in the data are 5_6-4_5 (251.826, Band 6 spw22/spw31) and 8_8-7_7 (344.311, Xb47 spw20).','high','scripts/s10_coverage.py -> out/s10_coverage.csv; s3c_scan.py -> out/s3c_scan.csv (5 sigma boxcar scan of all cubes)',target='all files',ass=A(rest_frequencies='Splatalogue/CDMS/JPL via astroquery (scripts/s0_linelist.py), rest = nu_obs/(1-2780/c)'))
add('Rest-frame spectral coverage (at 2780 km/s)','Band 5: 164.77-166.66 (spw22), 166.08-167.96 (spw20), 176.24-178.12 (spw16), 178.02-179.90 (spw18) GHz; Band 7: 342.04-343.86, 343.76-345.60, 353.90-355.72, 355.68-357.50; Band 6: 251.33-253.18, 253.10-254.95, 265.28-267.13, 267.06-268.91 GHz (all three Band-6 arrays identical)','high','out/s10_coverage.csv',unit='GHz')
add('Spectral line inventory >5 sigma (blind boxcar scan of N, S, peak pixel, r=8" spectra in all 20 cubes)','HCN 2-1,3-2,4-3; HCO+ 2-1,3-2,4-3; CS 7-6 (blend with H2CS 10_0-9_0/29SiO 8-7 not required by the data); CH3OH J_-1-J_0 E series blend (165.05-165.10 GHz; 12.7 sigma N, 20 sigma S in Xb55 at pixel); CO 3-2 blue wing (rest 345.2-345.6, band edge; N 170, S 333 mJy/beam in the last channel); HOC+ 2-1 (178.972, Xb55: N 8.5 sigma); weak, extended, array-dependent: SO 5_6-4_5 (S, 5.7 sigma, Xb4f only), 253.85-254.15 GHz bump (S, 9.5 sigma, Xb4f only). Nothing else at >5 sigma. Not detected: HC15N 4-3, SO 8_8-7_7, HCN-vib, SiS 14-13, H41beta RRL (matched filter N <0.23, S <0.48 Jy/beam km/s 3 sigma; forced-photometry 5.7 sigma hint at N is not confirmed)','high','out/s3c_scan.csv, out/s3d_forced.csv, out/s7c_weak_lines.csv, out/overview_*.png, out/zoom_candidates.png',unit='qualitative')
add('Vibrationally excited HCN','not separable: HCN v2=1e J=4-3 (354.460), 3-2 (265.853), 2-1 (177.239) lie only 35-40 km/s (<< line width 150-300 km/s) from the ground-state lines; HCN v2=1f 3-2 (267.199) at the Xb4f/Xb4d/Xb4b spw16/25 edge has no blue-side baseline; HCN v2=1f 4-3 (356.256) not detected: W<0.29 (N), <0.44 (S) Jy/beam km/s (3 sigma)','medium','out/s7c_weak_lines.csv',unit='Jy/beam km/s')
# ---- line table entries
for (_,r) in fit[(fit.spec=='pix')].iterrows():
    if ((r.ous in ('Xb55','Xb47','Xb4f')) and r.region not in ('N','S')): continue
    tar=f"{r.line} {r.region} ({r.ous}, beam {r.beam}\", peak pixel)"
    s=f"peak(raw channel)={r.peak_raw*1e3:.2f}, Tb_pk={r.Tb_peak_K:.2f} K; 1G: A={r.g1_A*1e3:.2f}+-{r.g1_A_e*1e3:.2f} mJy/beam, v0={r.g1_v0:.1f}+-{r.g1_v0_e:.1f} (dv_sys={r.g1_v0-VS:+.0f}), FWHM={r.g1_fwhm:.0f}+-{r.g1_fwhm_e:.0f} km/s, chi2r={r.g1_chi2r:.1f}; "
    if not np.isnan(r.get('g2_vblue',np.nan)): s+=f"2G(blue/red): v={r.g2_vblue-VS:+.0f}/{r.g2_vred-VS:+.0f}, A={r.g2_Ablue*1e3:.1f}/{r.g2_Ared*1e3:.1f} mJy/beam, chi2r={r.g2_chi2r:.2f}; "
    s+=f"I=int(|v-vsys|<{350 if 'CH3OH' not in r.line else 250} km/s)={r.W:.3f}+-{r.sigW:.3f} Jy/beam km/s ({r.W_Kkms:.0f} K km/s); rms/channel={r.rms_chan*1e3:.2f} mJy/beam"
    conf='high' if r.snr_W>20 else ('medium' if r.snr_W>5 else 'tentative')
    add('Line properties (see value)',s,conf,'scripts/s7a_extract_regions.py + s7b_fit_lines.py -> out/s7_line_fits.csv (beam-aperture rows spec=ap also there)',target=tar,unc='formal fit errors in text; 1G is a poor model for double-horned N profiles (chi2r 5-20): use 2G/integral',unit='mJy/beam, km/s, Jy/beam km/s')
# ---- regions
add('Distinct emission regions (HCO+/HCN 3-2, 0.25-0.9")','N nucleus (156.96346,-43.90390): double-horned, 1G FWHM 165 km/s, v0=sys+10; S nucleus (156.96340,-43.90532): line centre sys-60..-70 km/s, FWHM 105-125; Bridge (156.96357,-43.90457, 1.4" S of N): narrow 76-90 km/s, sys+3..+16; E1 (156.96606,-43.90353): 41-63 km/s wide, sys+50..+57; E2 (156.96548,-43.90540): 49-93 km/s, sys+71..+88; W (156.96114,-43.90590): 56-66 km/s, sys-6..0 (HCO+ only >5 sigma at 0.25"); Sblue (156.96305,-43.90611, 3" S of S nucleus): broad 117-230 km/s, centred at sys-37..-57, with blue wing: W_blue(-450..-150)=0.182+-0.010 (HCO+), 0.146+-0.017 (HCN) Jy/beam km/s at 0.94"','high','scripts/s5_moments.py -> out/mom_*.png, out/s5_moments.txt; out/s7_line_fits.csv; s8_wings.py -> out/s8_wings.csv',target='regions',ass=base_ass)
add('Region contrast HCN/HCO+ 3-2 (I_HCN/I_HCO+, peak pixel, |v|<350)','Xb4b 0.25": N 1.00, S 0.53, Bridge 0.54, E1 0.56, E2 0.51, Sblue 1.24 (low S/N); Xb4d 0.94": N 0.88, S 0.39, Bridge 0.50, E1 0.32, E2 0.42, Sblue 0.66, W 0.22; Xb4f 5.7x3.5": N 0.61, S 0.38; (preliminary: Q1 owns the matched-beam ratios)','medium','out/s7_line_fits.csv (ratio of W); beams differ per row; no common-beam convolution yet',target='regions',unc='~5-10% statistical for bright regions; flux scale cancels within a spw pair if same array',unit='ratio')
add('N and S separability per array','N-S separation 5.2" along PA~178; beam minor axis (N-S direction): Xb4b/Xb4d <=1", Xb47 2.7", Xb4f 3.5", Xb55 6.0". Beam cross-talk exp(-4ln2(5.2/theta)^2): Xb47 3e-5, Xb4f 2.5e-3, Xb55 0.12. N and S are independent in Bands 6/7 at all resolutions; in Band 5 (8.6x6.0") they are only partly resolved (up to 12% mutual contamination; peak spectra at N and S are nearly identical)','high','computed from beam headers (scripts/s2_extract.py beams)',target='all arrays',unit='fraction')
add('Wing flux fractions (blue -450..-150, red 150..450 km/s) in beam apertures','S nucleus: blue/core = 0.039 (HCO+ 3-2, Xb4d, 0.157+-0.006 Jy/beam km/s), 0.054 (HCN, 0.084+-0.012); Xb4b 0.037 (HCO+), 0.092 (HCN); N nucleus HCN 3-2 Xb4d red wing 0.112+-0.005 (2.4%), blue 0.055+-0.005; no wing at Bridge/E1/W (<2%); E2 red wing 0.091+-0.009 (HCO+, 7.6%), 0.069 (HCN, 13%)','medium','out/s8_wings.csv (noise = scatter of box sums in line-free channels; baseline systematics at low resolution ~0.1-0.4 Jy km/s => only the Xb4d/Xb4b numbers are trusted)',target='S, N, E2',unit='Jy/beam km/s',ass=A(caveat='wing channels (|v|>160 km/s) lie outside the pipeline clean mask (out/s9_maskcheck.txt): uncleaned, dirty-beam-affected'))
add('Clean-mask coverage','pipeline clean mask (Xb4d) covers 0.4-0.65% of pixels and only 63-74 of 478 channels; at N/S 36-46% of the |v|<350 km/s channels, 0-7% of the wing channels (150-400 km/s) are masked. High-velocity emission is therefore uncleaned in the delivered products (restored image + dirty residual)','high','scripts/s9_maskcheck.py -> out/s9_maskcheck.txt',unit='fraction')
# ---- blends & limits
for reg in ('N','S'):
    b=bl[(bl.model=='1-line')&(bl.region==reg)&(bl.template=='HCO+4-3')].iloc[0]
    b3=bl[(bl.model=='3-line')&(bl.region==reg)&(bl.template=='HCO+4-3')]
    ul=3*b3[b3.line.str.contains('H2CS')].err_boot.iloc[0]; ul2=3*b3[b3.line.str.contains('29SiO')].err_boot.iloc[0]
    add('CS 7-6 integrated intensity (template fit, beam aperture, Xb47 4.3x2.8")',f'{b.W_Jykms:.2f}+-{b3[b3.line=="CS 7-6"].err_boot.iloc[0]:.2f} Jy/beam km/s; blend limits (3 sigma): H2CS 10_0,10-9_0,9 (342.946) < {ul:.2f}, 29SiO 8-7 (342.981) < {ul2:.2f}','medium','scripts/s7d_blends.py -> out/s7d_blends.csv (NNLS, same-region HCO+ 4-3 profile as template; chi2r 1.17 N, 1.02 S; adding H2CS/29SiO does not improve the fit)',target=f'CS 7-6 {reg}',unit='Jy/beam km/s',ass=A(template='line profile of HCO+ 4-3 at same region/array; 3 lines are separated by only 31-56 km/s, so any blend is degenerate with the profile shape'))
add('H13CN 4-3 (345.340 GHz)','not separable from the CO 3-2 blue wing: N: I(low-frequency half of profile, +30..+300 km/s) = 1.19+-0.13 Jy/beam km/s, S: 0.65+-0.18 (these include CO wing => upper bounds on H13CN). With I(HCN 4-3, beam ap.) = 11.3 (N), 5.1 (S): HCN/H13CN > 7 (N), > 4 (S) (3 sigma); not a useful opacity constraint','low','scripts/s7d_blends.py (matched-filter on the low-frequency half) -> out/s7d_blends.csv; out/h13cn_cowing.png; high-frequency half and band edge (345.60) are dominated by CO 3-2 wing (S: 272 mJy/beam at 345.59)',target='Xb47 spw20 N, S',unit='ratio / Jy/beam km/s',ass=A(template='HCN 4-3 profile of the same region'))
