    add(f'{r.line} integrated intensity',f'{r.W_Jykms:.2f}+-{r.sigW:.2f} Jy/beam km/s: not detected; 3 sigma limit < {r.UL3_Jykms:.2f}','high','scripts/s7c_weak_lines.py -> out/s7c_weak_lines.csv (matched filter, HCN 4-3 profile template, beam aperture)',target=f'{r.region} (Xb47)',unit='Jy/beam km/s')
