add('Unidentified feature 253.85-254.15 GHz (rest)','Xb4f S beam aperture: I=0.53+-0.056 Jy/beam km/s (9.5 sigma, template fit) at 253.968; NS 11/2-9/2 Omega=1/2 f is the nominal assignment, but its partner e component (253.571) is not seen (S: -0.12+-0.11, <0.32 3 sigma) => NS identification disfavoured at ~5 sigma; other candidates (SO2 253.957, c-HCCCH 254.013, SiS 14-13 254.103 [3.7 sigma]) all high excitation; absent in Xb4d (<0.042) and Xb4b (<0.022): diffuse','tentative','out/s7c_weak_lines.csv, out/zoom_candidates.png (panel 1)',target='S',unit='Jy/beam km/s')
add('HC3N 28-27 (254.700)','Xb4f N 0.207+-0.056 (3.7 sigma), Xb4d N 0.042+-0.013 (3.2 sigma): marginal, not confirmed at 0.25" (<0.021 3 sigma); S: <0.37 (Xb4f)','tentative','out/s7c_weak_lines.csv',target='N',unit='Jy/beam km/s')
add('CH3OH J_-1-J_0 E series blend (165.050/165.061/165.099 GHz), Xb55 8.6x6.0"','N I=1.17+-0.09, S I=1.94+-0.10 Jy/beam km/s (peak 12 and 19 mJy/beam, rms 2 mJy; 250 km/s window; apertures give 1.04/1.49); S/N intensity ratio 1.7 (N,S only 12% cross-talk); detected at 12.7 / 20 sigma','medium','out/s7_line_fits.csv (spw22 rows); the three K lines are blended (spacing 11-40 MHz << line width), assignment from line list, centroid at sys-17 to -18 km/s relative to 165.061',target='N, S (Xb55)',unit='Jy/beam km/s',ass=A(identification='consistent with CH3OH 1_-1-1_0, 2_-1-2_0, 3_-1-3_0 E; other K ladders at 165.19-165.37 not checked individually'))
add('CO 3-2 blue wing at the Xb47 spw20 band edge','present: beam-aperture flux in the last channels (rest 345.60 GHz) N 170 mJy/beam, S 333 mJy/beam (CO 3-2 rest 345.796, i.e. -170 km/s) and still rising: the cube ends inside the CO line; the wing is relatively stronger toward S (S/N = 2.0 at the last channel vs 0.45 for HCN 4-3 and 0.7 for HCO+ 4-3) => S-nucleus/outflow CO likely; wing detectable down to about -450 km/s (345.28 GHz, ~3 sigma)','medium','out/h13cn_cowing.png, out/spectra/Xb47.spw20.cube.pbcor.npz',target='N, S',unit='mJy/beam')
