for _,r in weak[(weak.ous=='Xb55')&weak.line.isin(['H41beta RRL','CH3CN 9-8 K=0,1 (165.568)'])].iterrows():
    add(f'{r.line} (Xb55 beam aperture)',f'{r.W_Jykms:.2f}+-{r.sigW:.2f} Jy/beam km/s ({r.snr:.1f} sigma): {r.status}; 3 sigma limit < {r.UL3_Jykms:.2f}','tentative' if r.snr>=3 else 'medium','out/s7c_weak_lines.csv',target=f'{r.region} (Xb55)',unit='Jy/beam km/s')
